// Domain/Entities/Customer.cs: one class every team edits
public sealed class Customer : Entity
{
    public string Name { get; set; } = "";
    // Sales
    public decimal CreditLimit { get; set; }
    public bool IsVip { get; set; } // Sales and Support both set this
    // Shipping
    public List<Address> Addresses { get; set; } = [];
    // Support
    public int OpenTickets { get; set; }
}
// All the patterns are here, but "VIP" means two things in one class

namespace Sales
{
    // In Sales, a customer is someone we extend credit to
    public sealed class Customer(CustomerId id, Money creditLimit)
    {
        public CustomerId Id { get; } = id;
        public Money CreditLimit { get; private set; } = creditLimit;
        public DiscountTier Tier { get; private set; } = DiscountTier.Standard;
    }
}

namespace Support
{
    // In Support, the same person is a requester with a service level
    public sealed class Requester(CustomerId id, ServiceLevel level)
    {
        public CustomerId Id { get; } = id;
        public ServiceLevel Level { get; } = level;
    }
}
